def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def source(n,rel,start=None,end=None):
    path=f'workflows/tasks/certified_challenges/{families[n]}/{rel}';p=ROOT/path
    return {'path':path,'sha256':digest(p),'reviewed_lines':[[start or 1,end or len(p.read_text(encoding='utf8').splitlines())]]}
def artifact(name,key=None):return {'artifact':'dag/reviews/additional_challenges_021_030'+name,**({'key':key} if key else {})}

