def component_assessment(n,rel):
    common=f" Full C{n:03} family analysis and limits: AC2130-C{n:03}."
    if rel.endswith('__init__.py'):s='Read complete package initializer/import exports (including empty files); no certificate theorem is established by import scaffolding.'
    elif rel.endswith('conftest.py'):s='Read test import-path setup; this is test discovery scaffolding, not a sandbox or mathematical checker.'
    elif rel.endswith('CHALLENGE.md'):s='Read entire formal problem, declared domain, output obligations, planned implementations, arm statistics, budget claims and claim hygiene; planned provider/physics results are not treated as executed.'
    elif rel.endswith('TASK.md'):s='Read complete participant mathematical contract, wire examples and refusal rules; compared each against actual checker ingress and replay semantics.'
    elif rel.endswith('.md'):s='Read all operational and test-readiness prose; historical counts, LRAT/governance paths and empirical claims are assessed against actual pinned owners, not accepted as execution evidence.'
    elif 'generate' in rel:s='Read complete fixture/mutation generator, including write/delete entrypoints without executing them. Evaluated construction assumptions, corpus selection, canonical bytes and label validity; labels and reference agreement are not proof.'
